From 0086fcba44dd743c72504202bb49dc9671e04ffd Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 05:16:34 +0100
Subject: [PATCH] applets/systemtray: let keyboard focus move from popup to
 panel icons

After opening the System Tray with its shortcut, the arrow keys only
moved around the popup, so the icons shown in the panel could not be
reached. Moving past the popup's edge by the panel now focuses them.

BUG: 520583
---
 applets/systemtray/qml/HiddenItemsView.qml | 24 ++++++++++++++++++++++
 applets/systemtray/qml/main.qml            |  6 ++++++
 2 files changed, 30 insertions(+)

diff --git a/applets/systemtray/qml/HiddenItemsView.qml b/applets/systemtray/qml/HiddenItemsView.qml
index a7e6f967fd..ca93e1b4ae 100644
--- a/applets/systemtray/qml/HiddenItemsView.qml
+++ b/applets/systemtray/qml/HiddenItemsView.qml
@@ -10,8 +10,10 @@ pragma ComponentBehavior: Bound
 import QtQuick

 import org.kde.kirigami as Kirigami
+import org.kde.plasma.core as PlasmaCore
 import org.kde.plasma.components as PlasmaComponents3
 import org.kde.plasma.extras as PlasmaExtras
+import org.kde.plasma.plasmoid

 PlasmaComponents3.ScrollView {
     id: hiddenTasksView
@@ -64,6 +66,28 @@ PlasmaComponents3.ScrollView {

         KeyNavigation.up: hiddenTasksView.KeyNavigation.up

+        // Moving past the edge next to the panel focuses the icons shown there
+        Keys.onPressed: event => {
+            const column = currentIndex % columns;
+            const visualColumn = effectiveLayoutDirection === Qt.RightToLeft ? columns - 1 - column : column;
+            let pastEdge = false;
+            switch (Plasmoid.location) {
+            case PlasmaCore.Types.BottomEdge:
+                pastEdge = event.key === Qt.Key_Down && currentIndex + columns >= count;
+                break;
+            case PlasmaCore.Types.LeftEdge:
+                pastEdge = event.key === Qt.Key_Left && visualColumn === 0;
+                break;
+            case PlasmaCore.Types.RightEdge:
+                pastEdge = event.key === Qt.Key_Right && (visualColumn === columns - 1 || currentIndex === count - 1);
+                break;
+            }
+            if (pastEdge) {
+                root.focusVisibleItems();
+                event.accepted = true;
+            }
+        }
+
         onActiveFocusChanged: {
             if (activeFocus && currentIndex === -1) {
                 currentIndex = 0
diff --git a/applets/systemtray/qml/main.qml b/applets/systemtray/qml/main.qml
index b5cb44ce79..e78ff6159f 100644
--- a/applets/systemtray/qml/main.qml
+++ b/applets/systemtray/qml/main.qml
@@ -46,6 +46,12 @@ ContainmentItem {
         hiddenInstantiator.active = true;
     }

+    function focusVisibleItems() {
+        systemTrayState.expanded = false;
+        Plasmoid.containment.status = PlasmaCore.Types.AcceptingInputStatus;
+        root.nextItemInFocusChain()?.forceActiveFocus(Qt.TabFocusReason);
+    }
+
     Connections {
         target: Plasmoid
         function onActivated() {
-- 
